mmcfg.addMethod(CtNewMethod.make("""
public static String enc(int[] v, String pc) {
  String c = pkey(pc) ? pc : "def";
  if (v[0] == 160 && v[1] == 0 && v[2] == 500 && v[3] == 1 && v[4] == 1 && "def".equals(c)) return "";
  return "z" + v[0] + ".s" + (v[1] == 1 ? "q" : "r") + ".u" + v[2] + ".g" + v[3] + ".k" + v[4] + ".c" + c;
}""", mmcfg))
