wl.addMethod(CtNewMethod.make("""
public static boolean validAnchor(String a) {
  return a.equals("tl") || a.equals("t") || a.equals("tr") || a.equals("l") || a.equals("c") || a.equals("r") || a.equals("bl") || a.equals("b") || a.equals("br");
}""", wl))
wl.addMethod(CtNewMethod.make(f"""
public static {PKG}.WLayout parse(String s, {PKG}.WLayout def) {{
  try {{
    String[] p = s.trim().split(",");
    String a = p[1].trim();
    if (!validAnchor(a)) return def;
    int dx = Integer.parseInt(p[2].trim()); int dy = Integer.parseInt(p[3].trim()); int sc = Integer.parseInt(p[4].trim());
    if (sc < 50) sc = 50;
    if (sc > 200) sc = 200;
    {PKG}.WLayout w = new {PKG}.WLayout("1".equals(p[0].trim()), a, dx, dy, sc);
    if (def != null) {{ w.bw = def.bw; w.bh = def.bh; w.ldef = def.ldef; w.lines = def.ldef; w.mm = def.mm; w.fixed = def.fixed; if (def.fixed) w.scale = 100; }}
    if (p.length > 5) w.bg = "1".equals(p[5].trim());
    if (p.length > 6) {{ String c = p[6].trim(); int ci = palIdx(c); if (ci >= 0 && ci < TEXT_N) w.col = c; }}
    if (p.length > 7) w.bold = !"0".equals(p[7].trim());
    if (p.length > 8) w.ital = "1".equals(p[8].trim());
    if (p.length > 9) w.glow = "1".equals(p[9].trim());
    if (p.length > 10) {{ String g = p[10].trim(); if (palIdx(g) >= 0) w.gcol = g; }}
    if (p.length > 11) w.opt = !"0".equals(p[11].trim());
    if (p.length > 12) {{ try {{ int lv = Integer.parseInt(p[12].trim()); if (lv > 0) w.lines = lv; }} catch (Throwable x) {{ }} }}
    if (p.length > 13) {{ String o = p[13].trim(); int oi = palIdx(o); if (oi >= 0 && oi < TEXT_N) w.ocol = o; }}
    if (p.length > 14) w.mm = {PKG}.MmCfg.clean(p[14].trim());
    return w;
  }} catch (Throwable t) {{ return def; }}
}}""", wl))

