wid.addMethod(CtNewMethod.make("""
public static String[] partyModelU(java.util.UUID me, String myWorld, boolean opt) {
  String[] m = new String[17];
  m[0] = "P0";
  if (me == null) return m;
  java.util.Map b = bridge();
  String[] mem = callArr(b, "party:fn:members", me);
  if (mem == null || mem.length == 0) return m;
  String meS = me.toString();
  String leader = bstr(b, "party:leader:" + meS);
  if (leader == null || leader.trim().length() == 0) leader = mem[0];
  leader = leader == null ? "" : leader.trim();
  int n = mem.length;
  int shown = n < 5 ? n : 5;
  String[] sel = new String[shown];
  for (int i = 0; i < shown; i++) sel[i] = mem[i] == null ? "" : mem[i].trim();
  if (n > 5) {
    boolean found = false;
    for (int i = 0; i < shown; i++) if (meS.equalsIgnoreCase(sel[i])) found = true;
    if (!found) sel[4] = meS;
  }
  m[1] = "Party (" + n + ")";
  StringBuilder shape = new StringBuilder();
  shape.append("P").append(shown).append(":");
  for (int i = 0; i < shown; i++) {
    String us = sel[i];
    boolean self = meS.equalsIgnoreCase(us);
    String nm = bstr(b, "party:name:" + us);
    if (nm == null || nm.trim().length() == 0) nm = us.length() > 8 ? us.substring(0, 8) : us;
    nm = cut(nm, 14);
    if (leader.length() > 0 && us.equalsIgnoreCase(leader)) nm = nm + " (L)";
    String st = bstr(b, "party:stats:" + us);
    String line = "";
    boolean grey = false;
    if (st == null || st.trim().length() == 0) {
      line = "offline";
      grey = !self;
    } else {
      String[] p = splitc(st, ',');
      long hp = p.length > 0 ? lnum(p[0], 0L) : 0L;
      long mhp = p.length > 1 ? lnum(p[1], 0L) : 0L;
      long sta = p.length > 2 ? lnum(p[2], 0L) : 0L;
      long msta = p.length > 3 ? lnum(p[3], 0L) : 0L;
      long mp = p.length > 4 ? lnum(p[4], 0L) : 0L;
      long mmp = p.length > 5 ? lnum(p[5], 0L) : 0L;
      String w = "";
      if (p.length > 6) {
        StringBuilder wb = new StringBuilder();
        for (int j = 6; j < p.length; j++) { if (j > 6) wb.append(','); wb.append(p[j]); }
        w = wb.toString().trim();
      }
      // SkyyParty 0.1.3 writes the world name with commas turned into spaces: compare against both forms
      boolean same = self || myWorld == null || w.length() == 0 || w.equals(myWorld) || w.equals(myWorld.replace(',', ' ').trim());
      if (same) {
        line = "HP " + hp + "/" + mhp;
        if (opt) {
          line = line + "  ST " + sta + "/" + msta;
          if (mmp > 0L) line = line + "  MP " + mp + "/" + mmp;
        }
        grey = false;
      } else {
        line = "HP " + hp + "/" + mhp + " - " + worldFriendly(w, me);
        grey = true;
      }
    }
    m[2 + 3 * i] = nm;
    m[3 + 3 * i] = line;
    m[4 + 3 * i] = grey ? "1" : "0";
    shape.append(grey ? 'g' : 'n');
  }
  m[0] = shape.toString();
  return m;
}""", wid))
wid.addMethod(CtNewMethod.make("""
public static String[] guildModelU(java.util.UUID me, boolean opt) {
  String[] m = new String[6];
  m[0] = "G0";
  if (me == null) return m;
  java.util.Map b = bridge();
  String meS = me.toString();
  String gname = bstr(b, "guild:" + meS);
  if (gname == null || gname.trim().length() == 0) return m;
  String info = bstr(b, "guild:info:" + meS);
  String name = gname.trim(); String tag = ""; String lvl = "-"; long xp = -1L; long nx = -1L; String on = "-"; String tot = "-"; String rank = "";
  if (info != null) {
    String[] p = splitc(info, '|');
    if (p.length >= 8) {
      int k = p.length - 7;
      StringBuilder nb = new StringBuilder();
      for (int i = 0; i < k; i++) { if (i > 0) nb.append('|'); nb.append(p[i]); }
      if (nb.toString().trim().length() > 0) name = nb.toString().trim();
      tag = p[k].trim();
      if (p[k + 1].trim().length() > 0) lvl = p[k + 1].trim();
      xp = lnum(p[k + 2], -1L);
      nx = lnum(p[k + 3], -1L);
      if (p[k + 4].trim().length() > 0) on = p[k + 4].trim();
      if (p[k + 5].trim().length() > 0) tot = p[k + 5].trim();
      rank = p[k + 6].trim();
    }
  }
  m[1] = shorten(tag.length() > 0 ? "[" + tag + "] " + name : name, 28);
  String l2 = "Lv " + lvl;
  if (nx > 0L && xp >= 0L) l2 = l2 + "  (" + fmt(xp) + " / " + fmt(nx) + " XP)";
  else if (xp >= 0L) l2 = l2 + "  (" + fmt(xp) + " XP)";
  m[2] = l2;
  m[3] = "Online " + on + "/" + tot + (rank.length() > 0 ? "  |  " + rank : "");
  int rows = 0;
  if (opt) {
    String[] names = callArr(b, "guild:fn:online", me);
    if (names != null) {
      String ra = ""; String rb = ""; int c = 0;
      for (int i = 0; i < names.length && c < 4; i++) {
        String x = cut(names[i], 14);
        if (x.length() == 0) continue;
        if (c < 2) ra = ra.length() == 0 ? x : ra + ",  " + x;
        else rb = rb.length() == 0 ? x : rb + ",  " + x;
        c++;
      }
      if (ra.length() > 0) { m[4] = ra; rows = 1; }
      if (rb.length() > 0) { m[5] = rb; rows = 2; }
    }
  }
  m[0] = "G1:" + rows;
  return m;
}""", wid))
# 0.3.11 Skills model: [0] SHAPE "K<n>" ("K0" = hidden), [1] headline (first line "name level", null = hidden), [2 + 2k] name,
# [3 + 2k] level text of shown line k (null name = no line). Bridge reads only (memory): skill:fn:level present = SkyySkills loaded,
# skill:<uuid> = "Mining:12,Foraging:3,..." (SkyySkills levelsOf), skill:overall:<uuid> = Integer (SkyySkills' Overall Level, published
# every second), class:skill:<uuid> = the current class's weapon skill name (SkyyClasses). Never calls a Function (no file I/O here).
wid.addMethod(CtNewMethod.make("""
public static String skillVal(String[] parts, String label) {
  if (parts == null || label == null) return "-";
  String want = label.trim();
  if (want.length() == 0) return "-";
  for (int i = 0; i < parts.length; i++) {
    String p = parts[i];
    if (p == null) continue;
    int c = p.lastIndexOf(':');
    if (c <= 0) continue;
    if (!p.substring(0, c).trim().equalsIgnoreCase(want)) continue;
    long v = lnum(p.substring(c + 1), -1L);
    return v < 0L ? "-" : String.valueOf(v);
  }
  return "-";
}""", wid))
wid.addMethod(CtNewMethod.make("""
public static boolean skillsHave(java.util.Map b) {
  try { return b != null && b.get("skill:fn:level") != null; } catch (Throwable t) { return false; }
}""", wid))
# review fix (LOW 3): SkyyClasses loaded = its bridge key class:list (put once in setup() by every SkyyClasses version since 0.1,
# never removed). Without SkyyClasses there is no class skill, so the Class skill line is left out (it would read "Class skill  -"
# forever). skillsVis = the lines that can show; the shape then depends only on the mask and the installed mods (never flaps), and
# the Settings page's last-line rule and "Default" count only these lines
wid.addMethod(CtNewMethod.make("""
public static boolean classesHave(java.util.Map b) {
  try { return b != null && b.get("class:list") != null; } catch (Throwable t) { return false; }
}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static int skillsVis(java.util.Map b) {{
  return classesHave(b) ? {PKG}.WLayout.LINES_ALL : {PKG}.WLayout.LINES_ALL - {SKL_CLASS_BIT};
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static String[] skillsModelU(java.util.UUID me, int mask) {{
  String[] m = new String[{SKL_ARR}];
  m[0] = "K0";
  if (me == null) return m;
  java.util.Map b = bridge();
  if (!skillsHave(b)) return m;
  int vis = mask & skillsVis(b);
  String meS = me.toString();
  String lv = bstr(b, "skill:" + meS);
  String[] parts = null;
  if (lv != null) parts = splitc(lv, ',');
  String cls = bstr(b, "class:skill:" + meS);
  int n = 0;
  for (int k = 0; k < {PKG}.WLayout.LINE_N; k++) {{
    if ((vis & (1 << k)) == 0) continue;
    String name = {PKG}.WLayout.LINE_LABELS[k];
    String val = "-";
    if (k == 0) {{
      long o = lnum(bstr(b, "skill:overall:" + meS), -1L);
      val = o < 0L ? "-" : String.valueOf(o);
    }} else if (k == 1) {{
      if (cls != null && cls.trim().length() > 0) {{ name = cut(cls, 16); val = skillVal(parts, cls); }}
    }} else val = skillVal(parts, name);
    m[2 + 2 * n] = name;
    m[3 + 2 * n] = val;
    n++;
  }}
  if (n == 0) return m;
  m[0] = "K" + n;
  m[1] = m[2] + " " + m[3];
  return m;
}}""", wid))
# 0.3.12 Combat model: [0] SHAPE ("C0" hidden, "CI" in combat, "CO" the grey out-of-combat line; "S" = an editor / Settings sample,
# never a HUD shape), [1] headline (null = hidden), [2] name text, [3] countdown text ("" = none), [4] bar Value text "0.000" - "1.000"
# (null = no bar), [5] tone ("r" in combat = red or the picked colour, "g" grey, "n" the widget's own colour - the stand-in line).
