# 0.3.9 multi-line rendering (FLAT; see the 0.3.9 docstring). styleA = styleSrc with a chosen alignment. lineSrc = one text line
# whose line box is (x, y, w, h) in WIDGET coordinates: the 8 glow copies (0.3.7 offsets) and the real label are appended as DIRECT
# children of the widget Group with absolute anchors (the one-line widgets' structure - no wrapper Group); the real label sits in
# the line box inset by D on every side and each copy in the same inset box shifted by its offset (|offset| <= D, so never
# negative), which keeps Start/End aligned text glowing symmetrically. sc = effective size percent (HUD: layout scale; editor:
# scale x 2/3), minFs = smallest font (HUD 6, editor 5, as for the one-line widgets).
wid.addMethod(CtNewMethod.make(f"""
public static String styleA(int fs, {PKG}.WLayout l, String color, String align) {{
  return "Style: (FontSize: " + fs + ", RenderBold: " + (l.bold ? "true" : "false") + (l.ital ? ", RenderItalics: true" : "") + ", TextColor: " + color + ", HorizontalAlignment: " + align + ", VerticalAlignment: Center);";
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static String lineSrc(String base, int x, int y, int w, int h, int fs, {PKG}.WLayout l, String color, String gcolor, String align) {{
  StringBuilder sb = new StringBuilder();
  int d = (fs * 3 + 12) / 24;
  if (d < 1) d = 1;
  int e = (d + 1) / 2;
  int iw = w - 2 * d; if (iw < 1) iw = 1;
  int ih = h - 2 * d; if (ih < 1) ih = 1;
  if (l.glow) {{
    int[] ox = new int[] {{ -d, d, 0, 0, -e, e, -e, e }};
    int[] oy = new int[] {{ 0, 0, -d, d, -e, -e, e, e }};
    String gs = styleA(fs, l, gcolor, align);
    for (int k = 0; k < 8; k++) {{
      sb.append("Label #").append(base).append("G").append(k).append(" {{ Anchor: (Left: ").append(x + d + ox[k]).append(", Top: ").append(y + d + oy[k]).append(", Width: ").append(iw).append(", Height: ").append(ih).append("); Text: \\"\\"; ").append(gs).append(" }} ");
    }}
  }}
  sb.append("Label #").append(base).append("Txt {{ Anchor: (Left: ").append(x + d).append(", Top: ").append(y + d).append(", Width: ").append(iw).append(", Height: ").append(ih).append("); Text: \\"\\"; ").append(styleA(fs, l, color, align)).append(" }} ");
  return sb.toString();
}}""", wid))
# 0.3.13: the lines of a multi-line widget in a box w wide with padding p. lineS: Start text that begins exactly at p; lineE: End text
# that ends exactly p before the right edge. Each label reaches past its text to the glow distance d from the box edge (lineSrc insets
# a label by d; the glow copies stay inside the box), so a client that draws a text a few px wider than the font table never cuts it
wid.addMethod(CtNewMethod.make(f"""
public static String lineS(String base, int p, int y, int w, int h, int fs, {PKG}.WLayout l, String color, String gcolor) {{
  int d = (fs * 3 + 12) / 24;
  if (d < 1) d = 1;
  int lw = w - p - d; if (lw < 1) lw = 1;
  return lineSrc(base, p - d, y, lw + 2 * d, h, fs, l, color, gcolor, "Start");
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static String lineE(String base, int p, int y, int w, int h, int fs, {PKG}.WLayout l, String color, String gcolor) {{
  int d = (fs * 3 + 12) / 24;
  if (d < 1) d = 1;
  int lw = w - p - d; if (lw < 1) lw = 1;
  return lineSrc(base, 0, y, lw + 2 * d, h, fs, l, color, gcolor, "End");
}}""", wid))
# rows actually drawn (Party: member lines 0..5, Guild: online-name rows 0..2) and the drawn content height at size sc: ONE formula
# with the same floored parts partyBody / guildBody place their lines with - used for the widget Group height, the editor preview
# and every layout calculation of a multi-line widget
wid.addMethod(CtNewMethod.make("""
public static int partyRows(String[] m) {
  if (m == null) return 0;
  int n = 0;
  for (int i = 0; i < 5 && 4 + 3 * i < m.length; i++) { if (m[2 + 3 * i] == null) break; n = i + 1; }
  return n;
}""", wid))
wid.addMethod(CtNewMethod.make("""
public static int guildRows(String[] m) {
  if (m == null || m.length < 6 || m[4] == null) return 0;
  return m[5] != null ? 2 : 1;
}""", wid))
wid.addMethod(CtNewMethod.make("""
public static int skillRows(String[] m) {
  if (m == null) return 0;
  int n = 0;
  for (int i = 0; i < com.skyy.hud.WLayout.LINE_N && 3 + 2 * i < m.length; i++) { if (m[2 + 2 * i] == null) break; n = i + 1; }
  return n;
}""", wid))
# 0.3.11: the Skills height = SKL_TP (3) + rows x SKL_ROW (20) + SKL_TP, the floored parts skillsBody places its lines with (the two
# numbers are asserted where SKL_TP / SKL_ROW are defined; this method is not an f-string)
wid.addMethod(CtNewMethod.make("""
public static int bodyH(String id, String[] m, int sc) {
  if ("Skills".equals(id)) { int kp = 3 * sc / 100; return kp + skillRows(m) * (20 * sc / 100) + kp; }
  if ("Combat".equals(id)) { int cp = 3 * sc / 100; int cr = 20 * sc / 100; if (m != null && m.length > 4 && m[4] != null) { int cb = 6 * sc / 100; if (cb < 1) cb = 1; return cp + cr + cb + 8 * sc / 100; } return cp + cr + cp; }
  int tp = 3 * sc / 100; int th = 20 * sc / 100; int rh = 18 * sc / 100;
  if ("Party".equals(id)) return tp + th + partyRows(m) * rh + tp;
  int nh = 16 * sc / 100;
  return tp + th + 2 * rh + guildRows(m) * nh + tp;
}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static String partyBody(String base, {PKG}.WLayout l, int sc, String[] m, int minFs, int w) {{
  int p = padMl(sc, minFs); int tp = 3 * sc / 100;
  int th = 20 * sc / 100; int rh = 18 * sc / 100;
  int fsT = 12 * sc / 100; if (fsT < minFs) fsT = minFs;
  int fsR = 11 * sc / 100; if (fsR < minFs) fsR = minFs;
  int n = partyRows(m);
  StringBuilder sb = new StringBuilder();
  String col = hexOf(l.col);
  String gcol = glowHex(l) + "(0.45)";
  sb.append(lineS(base + "T", p, tp, w, th, fsT, l, col, gcol));
  for (int i = 0; i < n; i++) {{
    boolean grey = "1".equals(m[4 + 3 * i]);
    String c = grey ? GREY : col;
    String g = grey ? GREYG : gcol;
    int y = tp + th + i * rh;
    sb.append(lineS(base + "N" + i, p, y, w, rh, fsR, l, c, g));
    sb.append(lineE(base + "S" + i, p, y, w, rh, fsR, l, c, g));
  }}
  return sb.toString();
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static String guildBody(String base, {PKG}.WLayout l, int sc, String[] m, int minFs, int w) {{
  int sp = padMl(sc, minFs); int tp = 3 * sc / 100;
  int th = 20 * sc / 100; int rh = 18 * sc / 100; int nh = 16 * sc / 100;
  int fsT = 12 * sc / 100; if (fsT < minFs) fsT = minFs;
  int fsR = 11 * sc / 100; if (fsR < minFs) fsR = minFs;
  int fsN = 10 * sc / 100; if (fsN < minFs) fsN = minFs;
  int rows = guildRows(m);
  StringBuilder sb = new StringBuilder();
  String col = hexOf(l.col);
  String gcol = glowHex(l) + "(0.45)";
  sb.append(lineS(base + "T", sp, tp, w, th, fsT, l, col, gcol));
  sb.append(lineS(base + "L", sp, tp + th, w, rh, fsR, l, col, gcol));
  sb.append(lineS(base + "O", sp, tp + th + rh, w, rh, fsR, l, col, gcol));
  if (rows > 0) sb.append(lineS(base + "A", sp, tp + th + 2 * rh, w, nh, fsN, l, col, gcol));
  if (rows > 1) sb.append(lineS(base + "B", sp, tp + th + 2 * rh + nh, w, nh, fsN, l, col, gcol));
  return sb.toString();
}}""", wid))
wid.addMethod(CtNewMethod.make(f"""
public static String skillsBody(String base, {PKG}.WLayout l, int sc, String[] m, int minFs, int w) {{
  int sp = padMl(sc, minFs); int tp = {SKL_TP} * sc / 100;
  int rh = {SKL_ROW} * sc / 100;
  int fs = {SKL_FS} * sc / 100; if (fs < minFs) fs = minFs;
  int n = skillRows(m);
  StringBuilder sb = new StringBuilder();
  String col = hexOf(l.col);
  String gcol = glowHex(l) + "(0.45)";
  for (int i = 0; i < n; i++) {{
    int y = tp + i * rh;
    sb.append(lineS(base + "N" + i, sp, y, w, rh, fs, l, col, gcol));
    sb.append(lineE(base + "S" + i, sp, y, w, rh, fs, l, col, gcol));
  }}
  return sb.toString();
}}""", wid))
# 0.3.12 Combat colours: in combat the picked palette colour, or red #ff6b6b for "Default"; the stand-in line the widget's own colour.
# 0.3.13: out of combat the picked OUT-OF-COMBAT colour (WLayout.ocol); for "Default" the quiet party grey text + grey glow exactly as
