MMM(dsui, r"""
public static void settings(@UCB@ b, @UEB@ ev, @PR@ pr) {
  @PKG@.WLayout l = (@PKG@.WLayout) @PKG@.LayoutStore.get(pr.getUuid()).get("Seasons");
  if (l == null) return;
  boolean en = l.en;
  String anc = l.anchor == null ? "" : l.anchor;
  boolean home = "br".equals(anc) && l.dx == 0 && l.dy == 250;
  String dsText = @PKG@.DsLink.statusText();
""" + DSUI_JAVA + r"""
}""")
# a click: 0 = nothing, 1 = back, 2 = changed (saved; the caller re-sends and rebuilds the page)
MMM(dsui, r"""
public static int click(@PR@ pr, String data) {
  if (data == null) return 0;
  int p = data.indexOf("\"ds:");
  if (p < 0) return 0;
  int q = data.indexOf('"', p + 4);
  if (q < 0) return 0;
  String a = data.substring(p + 4, q);
  if (a.equals("back")) return 1;
  java.util.UUID u = pr.getUuid();
  @PKG@.WLayout l = (@PKG@.WLayout) @PKG@.LayoutStore.get(u).get("Seasons");
  if (l == null) return 0;
  if (a.equals("en:1")) l.en = true;
  else if (a.equals("en:0")) l.en = false;
  else if (a.equals("home")) { l.anchor = "br"; l.dx = 0; l.dy = 250; }
  else if (a.equals("reset")) { l.en = true; l.anchor = "br"; l.dx = 0; l.dy = 250; l.scale = 100; }
  else if (a.startsWith("an:")) { String an = a.substring(3); if (!@PKG@.WLayout.validAnchor(an)) return 0; @PKG@.Widgets.snapTo(l, an); }
  else return 0;
  @PKG@.Widgets.clampToScreen(l);
  @PKG@.LayoutStore.save(u);
  return 2;
}""")

# ================= HudMain =================
hudc.addField(CtField.make("public java.util.UUID uuid;", hudc))
hudc.addField(CtField.make("public long joinMs;", hudc))
hudc.addField(CtField.make("public final java.util.concurrent.ConcurrentHashMap last = new java.util.concurrent.ConcurrentHashMap();", hudc))
# 0.3.7: widget id -> Integer glow copy count of the document build() last sent (fill() only touches those elements)
hudc.addField(CtField.make("public final java.util.concurrent.ConcurrentHashMap built = new java.util.concurrent.ConcurrentHashMap();", hudc))
# 0.3.8: multi-line widget id -> SHAPE string its markup was built for (only for enabled Party/Guild layouts, "P0"/"G0" = hidden),
# id -> the String[] model build() used (fill(full) reuses it so build and its first fill agree), last shape rebuild time
hudc.addField(CtField.make("public final java.util.concurrent.ConcurrentHashMap shape = new java.util.concurrent.ConcurrentHashMap();", hudc))
hudc.addField(CtField.make("public final java.util.concurrent.ConcurrentHashMap models = new java.util.concurrent.ConcurrentHashMap();", hudc))
hudc.addField(CtField.make("public long lastRe;", hudc))
# 0.3.9: time of the confirm send (0 = none) - armed by build() when a Party / Guild widget appears or changes shape
hudc.addField(CtField.make("public long confirmAt;", hudc))
# 0.3.13: id -> the one-line text build() measured (its first fill sets exactly that), id -> Integer box width build() sent,
# id -> Long time the text first fitted a narrower box (cleared when it fits the built box again or needs more)
hudc.addField(CtField.make("public final java.util.concurrent.ConcurrentHashMap texts = new java.util.concurrent.ConcurrentHashMap();", hudc))
hudc.addField(CtField.make("public final java.util.concurrent.ConcurrentHashMap wb = new java.util.concurrent.ConcurrentHashMap();", hudc))
hudc.addField(CtField.make("public final java.util.concurrent.ConcurrentHashMap narrow = new java.util.concurrent.ConcurrentHashMap();", hudc))
hudc.addConstructor(CtNewConstructor.make(f"""
public HudMain({PR} pr) {{
  super(pr, "skyyhud_main");
  this.uuid = pr.getUuid();
  this.joinMs = System.currentTimeMillis();
}}""", hudc))
# 0.3.13: true = re-send the HUD for widget id: its text needs a wider box than the one sent (at once), or has fitted a narrower one for
# Widgets.SHRINK ms; called by fill on the 1 s tick only (never on a full build)
hudc.addMethod(CtNewMethod.make(f"""
public boolean widthMoved(String id, int need, long now) {{
  Object o = this.wb.get(id);
  if (o == null) return false;
  int have = ((Integer) o).intValue();
  if (need >= have) {{ this.narrow.remove(id); return need > have; }}
  Object t = this.narrow.get(id);
  if (t == null) {{ this.narrow.put(id, Long.valueOf(now)); return false; }}
  return now - ((Long) t).longValue() >= {PKG}.Widgets.SHRINK;
}}""", hudc))
hudc.addMethod(CtNewMethod.make(f"""
public boolean fill({UCB} b, boolean full) {{
  {PR} pr = getPlayerRef();
  String[] ids = {PKG}.Widgets.IDS;
  boolean re = false;
  long now = System.currentTimeMillis();
  for (int i = 0; i < ids.length; i++) {{
    if ({PKG}.Widgets.multi(ids[i])) {{
      Object sh = this.shape.get(ids[i]);
      if (sh == null) continue;
      {PKG}.WLayout ml = ({PKG}.WLayout) {PKG}.LayoutStore.get(this.uuid).get(ids[i]);
      String[] mm = null;
      if (full) mm = (String[]) this.models.get(ids[i]);
      if (mm == null) mm = {PKG}.Widgets.modelL(ids[i], pr, ml);
      if (!sh.equals(mm[0])) {{ re = true; continue; }}
      Object mg = this.built.get(ids[i]);
      if (mg == null) continue;
      if (!full && ml != null && widthMoved(ids[i], {PKG}.Widgets.multiW(ids[i], ml, mm, ml.scale, 6), now)) re = true;
      int gn = ((Integer) mg).intValue();
      String[] pairs = {PKG}.Widgets.linePairs(ids[i], mm);
      for (int k = 0; k + 1 < pairs.length; k += 2) {{
        String key = ids[i] + ":" + pairs[k];
        String lt = pairs[k + 1];
        String lp = (String) this.last.get(key);
        if (full || lp == null || !lp.equals(lt)) {{
          this.last.put(key, lt);
          {PKG}.Widgets.setText(b, "#SkyyW" + ids[i] + pairs[k], gn, lt);
        }}
      }}
      String bv = {PKG}.Widgets.barOf(ids[i], mm);
      if (bv != null) {{
        String bk = ids[i] + ":Bar";
        String bp = (String) this.last.get(bk);
        if (full || bp == null || !bp.equals(bv)) {{
          this.last.put(bk, bv);
          float fv = 0.0f;
          try {{ fv = Float.parseFloat(bv); }} catch (Throwable x) {{ fv = 0.0f; }}
          b.set("#SkyyW" + ids[i] + "Bar.Value", fv);
        }}
      }}
      continue;
    }}
    Object g = this.built.get(ids[i]);
    if (g == null) continue;
    String t = null;
    if (full) t = (String) this.texts.get(ids[i]);
    if (t == null) t = {PKG}.Widgets.text(ids[i], pr, this.joinMs);
    if (t == null) t = "";
    if (!full) {{
      {PKG}.WLayout ol = ({PKG}.WLayout) {PKG}.LayoutStore.get(this.uuid).get(ids[i]);
      if (ol != null && widthMoved(ids[i], {PKG}.Widgets.lineW(ol, t, ol.scale, 6), now)) re = true;
    }}
    String prev = (String) this.last.get(ids[i]);
    if (full || prev == null || !prev.equals(t)) {{
      this.last.put(ids[i], t);
      {PKG}.Widgets.setText(b, "#SkyyW" + ids[i], ((Integer) g).intValue(), t);
    }}
  }}
  return re;
}}""", hudc))
hudc.addMethod(CtNewMethod.make(f"""
protected void build({UCB} b) {{
  // 0.2.3: whole HUD sent inline (pattern from EndlessLeveling DungeonQueueHud) - no .ui document lookup on the client.
  b.appendInline((String) null, "Group #SkyyHudRoot {{ Anchor: (Full: 0); }}");
  java.util.Map m = {PKG}.LayoutStore.get(this.uuid);
  String[] ids = {PKG}.Widgets.IDS;
  java.util.HashMap oldShape = new java.util.HashMap(this.shape);
  this.built.clear();
  this.shape.clear();
  this.models.clear();
  this.texts.clear();
  this.wb.clear();
  this.narrow.clear();
  {PR} pr = getPlayerRef();
  for (int i = 0; i < ids.length; i++) {{
    {PKG}.WLayout l = ({PKG}.WLayout) m.get(ids[i]);
    if (l == null || !l.en) continue;
    if ("Minimap".equals(ids[i]) || "Seasons".equals(ids[i])) continue;
    if ({PKG}.Widgets.multi(ids[i])) {{
      String[] mm = {PKG}.Widgets.modelL(ids[i], pr, l);
      this.shape.put(ids[i], mm[0]);
      this.models.put(ids[i], mm);
      if (!{PKG}.Widgets.shown(mm)) continue;
      if (!mm[0].equals(oldShape.get(ids[i]))) this.confirmAt = System.currentTimeMillis() + 1500L;
      int mw = {PKG}.Widgets.multiW(ids[i], l, mm, l.scale, 6);
      this.wb.put(ids[i], Integer.valueOf(mw));
      b.appendInline("#SkyyHudRoot", {PKG}.Widgets.multiWidgetSrcW(ids[i], l, mm, mw));
      this.built.put(ids[i], Integer.valueOf({PKG}.Widgets.glowCount(l)));
      continue;
    }}
    // 0.3.13: measure the text first - the box is as wide as it (+ P a side); the first fill sets exactly this text
    String t = {PKG}.Widgets.text(ids[i], pr, this.joinMs);
    if (t == null) t = "";
    int ow = {PKG}.Widgets.lineW(l, t, l.scale, 6);
    this.texts.put(ids[i], t);
    this.wb.put(ids[i], Integer.valueOf(ow));
    b.appendInline("#SkyyHudRoot", {PKG}.Widgets.widgetSrcW(ids[i], l, ow));
    this.built.put(ids[i], Integer.valueOf({PKG}.Widgets.glowCount(l)));
  }}
  this.last.clear();
  fill(b, true);
}}""", hudc))
# tick (scheduler thread), rebuild (world thread, page clicks) and the first show (attach) share the HudMain monitor, so an
# update built from one document can never be sent after/before the show() of another
hudc.addMethod(CtNewMethod.make(f"""
public synchronized void tick() {{
  try {{
    {UCB} b = new {UCB}();
    boolean re = fill(b, false);
    long now = System.currentTimeMillis();
    if (re) {{
      if (now - this.lastRe >= 1500L) {{ this.lastRe = now; show(); return; }}
    }} else if (this.confirmAt != 0L && now >= this.confirmAt) {{
      this.confirmAt = 0L; show(); return;
    }}
    if (b.getCommands().length > 0) update(false, b);
  }} catch (Throwable t) {{ }}
}}""", hudc))
hudc.addMethod(CtNewMethod.make("""
public synchronized void rebuild() {
  try { show(); } catch (Throwable t) { }
}""", hudc))
hudc.addMethod(CtNewMethod.make("""
public synchronized void showNow() {
  show();
}""", hudc))

