pl.addMethod(CtNewMethod.make(f"""
public void tickAll() {{
  java.util.Iterator it = this.huds.entrySet().iterator();
  while (it.hasNext()) {{
    java.util.Map.Entry e = (java.util.Map.Entry) it.next();
    {PKG}.HudMain h = ({PKG}.HudMain) e.getValue();
    {PR} pr = h.getPlayerRef();
    if (pr == null || !pr.isValid()) {{ it.remove(); {PKG}.LayoutStore.CACHE.remove(e.getKey()); {PKG}.EditorPage.STEPS.remove(e.getKey()); continue; }}
    h.tick();
  }}
}}""", pl))

